PERSON_SUFFIX = "full body, standing, isolated on a pure white background, centered, whole figure in frame, sharp focus, studio lighting"


def build_groups():
    objects = KITCHEN + ELECTRONICS + FURNITURE + TOOLS + TOYS + FASHION + JEWELRY + SPORTS + INSTRUMENTS + VEHICLES + FOOD + DECOR + STATIONERY + FANTASY
    living = ANIMALS + PLANTS
    persons = PEOPLE + CHARACTERS
    return [
        (objects, OBJECT_ADJ, OBJECT_STYLES, OBJECT_SUFFIX),
        (living, LIVING_ADJ, LIVING_STYLES, LIVING_SUFFIX),
        (persons, PERSON_ADJ, PERSON_STYLES, PERSON_SUFFIX),
    ]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--target", type=int, default=100_000)
    parser.add_argument("--out", default=str(OUT))
    args = parser.parse_args()

    rng = random.Random(42)
    groups = build_groups()
    total_subjects = sum(len(g[0]) for g in groups)
    per_subject = math.ceil(args.target / total_subjects)

    prompts = []
    seen = set()
    for subjects, adjs, styles, suffix in groups:
        combos = list(itertools.product(adjs, styles))
        for subj in subjects:
            rng.shuffle(combos)
            for adj, style in combos[:per_subject]:
                head = f"{adj} {subj}".strip()
                p = f"{head}, {style}, {suffix}"
                if p not in seen:
                    seen.add(p)
                    prompts.append(p)

    rng.shuffle(prompts)
    prompts = prompts[: args.target]

    out = Path(args.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w") as f:
        for p in prompts:
            f.write(json.dumps({"prompt": p}) + "\n")
    print(f"{len(prompts)} prompts -> {out} ({total_subjects} subjects, {per_subject}/subject)")


if __name__ == "__main__":
    main()
